import {Solver, STEP, RADII, MAX_SPEED, SOLUTION} from './physics.js';
import {createView} from './view.js';
import {LEVELS, applyLevel} from './levels.js';
const $=s=>document.querySelector(s), canvas=$('#world'), layer=$('#aim'), ctx=layer.getContext('2d');
const solver=new Solver(), history=[];let view, flow='title', selected=null, pointer=null, origin=null, velocity={x:0,y:0},strength=0,acc=0,last=0,winAge=0,demo=false,demoIndex=0,demoWait=0,muted=false,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,best={},completed={},levelIndex=0,taught=false,frozen=false,prediction=[];
try{const p=JSON.parse(localStorage.getItem('bunbreak-web')||'{}');best=typeof p.best==='object'&&p.best?p.best:{};completed=p.completed||{};levelIndex=Number.isInteger(p.levelIndex)?Math.max(0,Math.min(5,p.levelIndex)):0;muted=!!p.muted;reduced=p.reduced??reduced;taught=!!p.taught;}catch{}
const save=()=>{try{localStorage.setItem('bunbreak-web',JSON.stringify({best,completed,levelIndex,muted,reduced,taught}));}catch{}};
let audio,lastSound=0;
function sound(freq){if(muted||performance.now()-lastSound<70)return;lastSound=performance.now();try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime;o.type='sine';o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(freq*.72,t+.16);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.07,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+.21);o.connect(g).connect(audio.destination);o.start();o.stop(t+.22);}catch{}}
function flash(text){if(reduced)return;const el=$('#flash');el.textContent=text;el.classList.remove('pop');void el.offsetWidth;el.classList.add('pop');}
function cancel(){if(selected!==null)view?.cancelAim(selected);selected=null;pointer=null;strength=0;prediction=[];drawAim();}
function action(text,fn,primary=false){const b=document.createElement('button');b.textContent=text;if(primary)b.className='primary';b.onclick=()=>{audio?.resume();fn();};$('#actions').append(b);return b;}
function show(next){cancel();flow=next;const overlay=$('#overlay');overlay.hidden=next==='play';overlay.className=next;$('#hud').hidden=next!=='play';$('#cue').hidden=next!=='play';$('#actions').replaceChildren();$('#stars').textContent='';$('#footnote').textContent='';$('#kicker').textContent='SUNSHINE KITCHEN';
 if(next==='title'){$('#heading').textContent='Bunbreak';$('#message').textContent='A little pull. A happy wobble.';action(Object.keys(completed).length?'Continue':'Play',start,true);action('Kitchen trail',()=>show('trail'));$('#footnote').textContent='Six little puzzles. One happy kitchen.';}
 if(next==='pause'){$('#heading').textContent='A little breather';$('#message').textContent='The buns can wait.';action('Keep playing',()=>show('play'),true);action('Start over',start);action('Show me',showMe);action(muted?'Sound: off':'Sound: on',()=>{muted=!muted;save();show('pause');});action(reduced?'Motion: gentle':'Motion: full',()=>{reduced=!reduced;view.setReducedMotion(reduced);save();show('pause');});action('Kitchen trail',()=>show('trail'));}
 if(next==='result'){$('#heading').textContent=demo?'That’s the recipe!':'Sweet freedom!';$('#message').textContent=demo?'Your turn. Give those buns a little pull.':`${solver.shots} shots. A happy escape!`;if(!demo){const stars=solver.shots<=LEVELS[levelIndex].mastery?3:solver.shots<=LEVELS[levelIndex].generous?2:1;$('#stars').textContent='★'.repeat(stars)+'☆'.repeat(3-stars);$('#stars').ariaLabel=`${stars} of 3 wafer stars`;}action(demo?'Your turn':levelIndex<LEVELS.length-1?'Next puzzle':'Play again',()=>{if(!demo&&levelIndex<LEVELS.length-1)levelIndex++;start();},true);action('Play again',start);action('Kitchen trail',()=>show('trail'));$('#footnote').textContent='Unlimited tries. Take your time.';}
 if(next==='trail'){$('#heading').textContent='The kitchen trail';$('#message').textContent='Choose a little adventure.';LEVELS.forEach((level,i)=>{const unlocked=i===0||completed[LEVELS[i-1].id]||completed[level.id];const b=action(`${i+1}  ${level.title} · ${completed[level.id]?'✓':unlocked?'Play':'Locked'}`,()=>{levelIndex=i;start();},i===levelIndex);b.disabled=!unlocked;});action('Back',()=>show('title'));}
 updateHUD();}
function start(){applyLevel(solver,levelIndex);save();history.length=0;acc=0;winAge=0;demo=false;$('#flash').classList.remove('pop');$('#flash').textContent='';view?.reset();view?.configureLevel(LEVELS[levelIndex]);view?.setBuns(solver.buns,1);show('play');sound(440);}
function showMe(){start();demo=true;demoIndex=0;demoWait=.7;}
function undo(){if(!history.length||flow!=='play')return;cancel();demo=false;solver.restore(history.pop());acc=0;winAge=0;view.reset();view.configureLevel(LEVELS[levelIndex]);view.setGateOpen(solver.gateOpen);view.setBuns(solver.buns,1);updateHUD();}
function updateHUD(){$('#level-name').textContent=LEVELS[levelIndex].title.toUpperCase();$('#shots').textContent=`${solver.shots} shot${solver.shots===1?'':'s'}`;$('#undo').disabled=!history.length;$('#cue').textContent=demo?'Watch the buns… then try your own shot.':selected!==null?'Hold… and let go.':solver.isMoving()?'Boing…':!taught?'Pull backwards from a bun. Release to flick.':LEVELS[levelIndex].goal;}
function resize(){view?.resize();const r=canvas.getBoundingClientRect();layer.width=Math.round(r.width*devicePixelRatio);layer.height=Math.round(r.height*devicePixelRatio);ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);drawAim();}
function drawAim(){const r=canvas.getBoundingClientRect();ctx.clearRect(0,0,r.width,r.height);if(!view)return;const badge=$('#gate-badge');badge.hidden=solver.gateOpen;const marker=view.screenFromWorld({x:0,y:solver.level.gateY});badge.style.left=`${marker.x-r.left}px`;badge.style.top=`${marker.y-r.top}px`;badge.textContent=['','PIP','BERRY','MANGO'][solver.level.requiredTier];badge.dataset.tier=solver.level.requiredTier;if(selected===null)return;const bun=solver.findBun(selected);if(!bun)return;const center=view.screenFromWorld(bun.position);ctx.strokeStyle='#fff1bd';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(center.x-r.left,center.y-r.top,23,14,0,0,Math.PI*2);ctx.stroke();prediction.forEach((p,i)=>{const s=view.screenFromWorld(p);ctx.globalAlpha=.8-i/prediction.length*.6;ctx.fillStyle='#fff1bd';ctx.beginPath();ctx.arc(s.x-r.left,s.y-r.top,Math.max(1.5,3-i*.035),0,Math.PI*2);ctx.fill();});ctx.globalAlpha=1;}
function begin(e){if(flow!=='play'||solver.won||solver.isMoving()||selected!==null)return;const p=view.worldFromScreen(e.clientX,e.clientY);selected=view.pickBun?.(e.clientX,e.clientY)??null;let d=Infinity;if(selected===null)for(const b of solver.buns){const distance=Math.hypot(p.x-b.position.x,p.y-b.position.y);if(distance<RADII[b.tier]+.25&&distance<d){selected=b.id;d=distance;}}if(selected===null)return;demo=false;pointer=e.pointerId;origin=p;canvas.setPointerCapture(pointer);view.aim(selected,{x:0,y:0},0);e.preventDefault();updateHUD();}
function drag(e){if(selected===null||pointer!==e.pointerId)return;const p=view.worldFromScreen(e.clientX,e.clientY),dx=origin.x-p.x,dy=origin.y-p.y,dist=Math.hypot(dx,dy);strength=Math.min(dist/2.2,1);velocity={x:dist?dx/dist*MAX_SPEED*strength:0,y:dist?dy/dist*MAX_SPEED*strength:0};view.aim(selected,{x:dist?dx/dist:0,y:dist?dy/dist:0},strength);prediction=[];if(strength>.04){const s=new Solver();s.restore(solver.snapshot());s.shoot(selected,velocity);for(let i=0;i<90;i++){s.step();const b=s.findBun(selected);if(!b)break;if(i%5===0)prediction.push({...b.position});}}drawAim();e.preventDefault();}
function end(e,canceled=false){if(pointer!==e.pointerId||selected===null)return;const rect=canvas.getBoundingClientRect(),inside=e.clientX>=rect.left&&e.clientX<=rect.right&&e.clientY>=rect.top&&e.clientY<=rect.bottom;const id=selected;if(!canceled&&inside&&strength>=.045){history.push(solver.snapshot());solver.shoot(id,velocity);taught=true;save();selected=null;pointer=null;prediction=[];consume();}else cancel();drawAim();updateHUD();}
function consume(){if(!solver.events.length)return;const events=solver.events.splice(0);view.setBuns(solver.buns,1);view.syncEvents(events,solver.buns);for(const e of events){if(e.type==='release')sound(420);if(e.type==='merge'){sound(660);flash(e.tier===3?'Hello, Mango!':'Better together!');}if(e.type==='jelly')sound(240);if(e.type==='gate'){sound(880);flash('Crumb-believable!');}if(e.type==='escape'){sound(1040);if(!demo){const id=LEVELS[levelIndex].id;completed[id]=true;if(!best[id]||solver.shots<best[id])best[id]=solver.shots;save();}}}}
function advance(dt,draw=true){if(flow==='play'){acc+=Math.min(dt,.15);while(acc+1e-10>=STEP){solver.step();acc-=STEP;}consume();if(demo&&!solver.won){if(solver.isMoving())demoWait=.75;else{demoWait-=dt;const m=LEVELS[levelIndex].solution[demoIndex];if(m){const len=Math.hypot(m.vx,m.vy);if(demoWait>0)view.aim(m.id,{x:m.vx/len,y:m.vy/len},len/MAX_SPEED*Math.min(1,Math.max(0,(.75-demoWait)/.45)));else{history.push(solver.snapshot());solver.shoot(m.id,{x:m.vx,y:m.vy});demoIndex++;demoWait=.75;consume();}}}}if(solver.won){winAge+=dt;if(winAge>(reduced?.2:1.0))show('result');}}
 view.setBuns(solver.buns,Math.max(0,Math.min(1,acc/STEP)));if(draw){if(flow!=='pause'&&flow!=='trail')view.render(dt);drawAim();}updateHUD();}
$('#undo').onclick=undo;$('#pause').onclick=()=>show('pause');canvas.addEventListener('pointerdown',begin);canvas.addEventListener('pointermove',drag);canvas.addEventListener('pointerup',e=>end(e));canvas.addEventListener('pointercancel',e=>end(e,true));canvas.addEventListener('lostpointercapture',()=>{if(selected!==null)cancel();});window.addEventListener('blur',()=>{cancel();if(flow==='play')show('pause');});document.addEventListener('visibilitychange',()=>{if(document.hidden&&flow==='play'){cancel();show('pause');}});window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(flow==='play')show('pause');else if(flow==='pause')show('play');else show('title');}});window.addEventListener('resize',resize);
try{applyLevel(solver,levelIndex);view=await createView(canvas);view.setReducedMotion(reduced);view.configureLevel(LEVELS[levelIndex]);view.setBuns(solver.buns,1);resize();$('#loading').hidden=true;show('title');requestAnimationFrame(function loop(t){const dt=last?Math.min((t-last)/1000,.1):1/60;last=t;if(!frozen)advance(dt);requestAnimationFrame(loop);});window.__bunbreak={start,showMe,undo,chooseLevel:i=>{levelIndex=i;start();},pause:()=>show('pause'),resume:()=>show('play'),freeze:()=>frozen=true,unfreeze:()=>frozen=false,advance,inspect:()=>({flow,levelIndex,buns:structuredClone(solver.buns),gateOpen:solver.gateOpen,shots:solver.shots,won:solver.won,motion:view.inspect?.()}),screenFor:id=>view.screenFromWorld(solver.findBun(id).position),aim:(id,dir,s)=>view.aim(id,dir,s),release:(id,v)=>{history.push(solver.snapshot());solver.shoot(id,v);consume();},cancelAim:id=>view.cancelAim(id)};}catch(error){console.error(error);$('#loading').innerHTML='<p>The kitchen couldn’t load. Please reload and try again.</p>';}
